def check_no_ap3(coloring):
    n = len(coloring)
    for a in range(1, n + 1):
        for d in range(1, n + 1):
            if a + 2 * d <= n:
                if coloring[a-1] == coloring[a+d-1] == coloring[a+2*d-1]:
                    return False, (a, a+d, a+2*d)
    return True, None

# Let's verify W(3,3) = 27
# If W(3,3) = 27, then any coloring of 27 elements with 3 colors has an AP3.
# Let's try to find a coloring for a smaller number, say 26.
# Actually, let's just use a solver to check if 27 is indeed the limit.
from z3 import *

def solve_van_der_waerden(n, num_colors):
    s = Solver()
    x = [Int(f'x_{i}') for i in range(n)]
    for i in range(n):
        s.add(x[i] >= 0, x[i] < num_colors)

    for a in range(1, n + 1):
        for d in range(1, n + 1):
            if a + 2 * d <= n:
                s.add(Or(x[a-1] != x[a+d-1], x[a+d-1] != x[a+2*d-1]))

    return s.check()

print(solve_van_der_waerden(26, 3))
print(solve_van_der_waerden(27, 3))
